import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.DaAAbehN.js";const u=JSON.parse(`{"title":"Lesson 8: File Operations — Codex's Most Basic Capability","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-3/lesson-8.md","filePath":"en/modules/module-3/lesson-8.md"}`),o={name:"en/modules/module-3/lesson-8.md"};function n(l,e,d,r,p,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="lesson-8-file-operations-—-codex-s-most-basic-capability" tabindex="-1">Lesson 8: File Operations — Codex&#39;s Most Basic Capability <a class="header-anchor" href="#lesson-8-file-operations-—-codex-s-most-basic-capability" aria-label="Permalink to &quot;Lesson 8: File Operations — Codex&#39;s Most Basic Capability&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Master the basic methods for reading, editing, and organizing files with Codex ⏱️ <strong>Estimated Time</strong>: 25 minutes 🎯 <strong>Teaching Rhythm</strong>: Demo first → Explain → Practice</p></blockquote><hr><h2 id="i-codex-can-read-files-on-your-computer" tabindex="-1">I. Codex Can Read Files on Your Computer <a class="header-anchor" href="#i-codex-can-read-files-on-your-computer" aria-label="Permalink to &quot;I. Codex Can Read Files on Your Computer&quot;">​</a></h2><p>This is one of Codex&#39;s most basic and core capabilities.</p><h3 id="_1-1-drag-and-drop-files-into-the-chat" tabindex="-1">1.1 Drag and Drop Files into the Chat <a class="header-anchor" href="#_1-1-drag-and-drop-files-into-the-chat" aria-label="Permalink to &quot;1.1 Drag and Drop Files into the Chat&quot;">​</a></h3><p>Open Codex and directly drag files into the chat box or workspace:</p><ul><li><strong>Text files</strong> (.txt, .md, .csv) → Codex can read the content directly</li><li><strong>Code files</strong> (.py, .js, .html) → Codex can analyze and modify them</li><li><strong>Image files</strong> (.jpg, .png) → Codex can recognize the content in the image</li><li><strong>PDF files</strong> → Codex can extract text and summarize</li></ul><h3 id="_1-2-let-codex-read-a-folder" tabindex="-1">1.2 Let Codex Read a Folder <a class="header-anchor" href="#_1-2-let-codex-read-a-folder" aria-label="Permalink to &quot;1.2 Let Codex Read a Folder&quot;">​</a></h3><p>Besides individual files, you can also have Codex read an entire folder:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me see what files are in this folder.</span></span></code></pre></div><p>Codex will list all file names, sizes, modification dates, and other information.</p><hr><h2 id="ii-practice-1-let-codex-help-you-organize-documents" tabindex="-1">II. Practice 1: Let Codex Help You Organize Documents <a class="header-anchor" href="#ii-practice-1-let-codex-help-you-organize-documents" aria-label="Permalink to &quot;II. Practice 1: Let Codex Help You Organize Documents&quot;">​</a></h2><h3 id="scenario" tabindex="-1">Scenario <a class="header-anchor" href="#scenario" aria-label="Permalink to &quot;Scenario&quot;">​</a></h3><p>You have a &quot;messy documents&quot; folder containing:</p><ul><li>Word documents (.docx)</li><li>PDF files</li><li>Excel spreadsheets (.xlsx)</li><li>Text files (.txt)</li></ul><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Open the folder as the workspace in Codex</li><li>Type this command:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me organize this folder. Create subfolders by file type and move similar files into them.</span></span></code></pre></div></li><li>Codex will: <ul><li>Scan all files</li><li>Create subfolders like <code>documents/</code>, <code>pdfs/</code>, <code>spreadsheets/</code>, <code>text-files/</code></li><li>Move files to the corresponding locations</li></ul></li></ol><h3 id="advanced-commands" tabindex="-1">Advanced Commands <a class="header-anchor" href="#advanced-commands" aria-label="Permalink to &quot;Advanced Commands&quot;">​</a></h3><p>If you want more fine-grained control:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Move all PDF files in this folder into a subfolder named &quot;reports&quot;</span></span></code></pre></div><p>or</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Find all files larger than 10MB and move them to a &quot;large-files&quot; folder.</span></span></code></pre></div><hr><h2 id="iii-practice-2-batch-rename-files" tabindex="-1">III. Practice 2: Batch Rename Files <a class="header-anchor" href="#iii-practice-2-batch-rename-files" aria-label="Permalink to &quot;III. Practice 2: Batch Rename Files&quot;">​</a></h2><h3 id="scenario-1" tabindex="-1">Scenario <a class="header-anchor" href="#scenario-1" aria-label="Permalink to &quot;Scenario&quot;">​</a></h3><p>You have a batch of photos with filenames like <code>IMG_001.jpg</code>, <code>IMG_002.jpg</code>... and you want to give them more meaningful names.</p><h3 id="steps-1" tabindex="-1">Steps <a class="header-anchor" href="#steps-1" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Open the photos folder as the workspace</li><li>Type this command:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Rename these photos to the format &quot;Trip-Sequence.jpg&quot;, e.g., &quot;Trip-001.jpg&quot;</span></span></code></pre></div></li><li>Codex will execute the batch rename.</li></ol><h3 id="more-examples" tabindex="-1">More Examples <a class="header-anchor" href="#more-examples" aria-label="Permalink to &quot;More Examples&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Your Command</th><th>What Codex Does</th></tr></thead><tbody><tr><td>&quot;Change all .JPG to .jpg&quot;</td><td>Unify extension case to lowercase</td></tr><tr><td>&quot;Add the date prefix 20260722 to all filenames&quot;</td><td>Add a date prefix</td></tr><tr><td>&quot;Remove all spaces from filenames&quot;</td><td>Clean up filenames</td></tr></tbody></table><hr><h2 id="iv-practice-3-analyze-folder-disk-usage" tabindex="-1">IV. Practice 3: Analyze Folder Disk Usage <a class="header-anchor" href="#iv-practice-3-analyze-folder-disk-usage" aria-label="Permalink to &quot;IV. Practice 3: Analyze Folder Disk Usage&quot;">​</a></h2><h3 id="scenario-2" tabindex="-1">Scenario <a class="header-anchor" href="#scenario-2" aria-label="Permalink to &quot;Scenario&quot;">​</a></h3><p>Your hard drive is nearly full, and you want to know what&#39;s taking up space.</p><h3 id="steps-2" tabindex="-1">Steps <a class="header-anchor" href="#steps-2" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Open the target folder (e.g., the entire &quot;Downloads&quot; folder)</li><li>Type this command:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me analyze the disk space usage of this folder and list the top 10 largest files.</span></span></code></pre></div></li><li>Codex will generate a report like this:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>📊 Folder Space Analysis Report</span></span>
<span class="line"><span>Total size: 4.2 GB</span></span>
<span class="line"><span>Total files: 328</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Top 10 Largest Files:</span></span>
<span class="line"><span>1. video_backup.mp4 — 1.2 GB</span></span>
<span class="line"><span>2. database_dump.sql — 850 MB</span></span>
<span class="line"><span>3. project_archive.zip — 620 MB</span></span>
<span class="line"><span>...</span></span></code></pre></div><hr><h2 id="v-can-codex-edit-files" tabindex="-1">V. Can Codex Edit Files? <a class="header-anchor" href="#v-can-codex-edit-files" aria-label="Permalink to &quot;V. Can Codex Edit Files?&quot;">​</a></h2><p><strong>Yes!</strong> And this is one of its very powerful capabilities.</p><h3 id="example-modifying-a-text-file" tabindex="-1">Example: Modifying a Text File <a class="header-anchor" href="#example-modifying-a-text-file" aria-label="Permalink to &quot;Example: Modifying a Text File&quot;">​</a></h3><p>Suppose you have a <code>notes.txt</code> file with this content:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>To-do list:</span></span>
<span class="line"><span>1. Buy milk</span></span>
<span class="line"><span>2. Pay rent</span></span>
<span class="line"><span>3. Book a dentist appointment</span></span></code></pre></div><p>You can tell Codex:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add one more item to this to-do list: &quot;Book a haircut appointment&quot;, at the end.</span></span></code></pre></div><p>Codex will directly modify the original file and add the new item.</p><h3 id="example-formatting-data" tabindex="-1">Example: Formatting Data <a class="header-anchor" href="#example-formatting-data" aria-label="Permalink to &quot;Example: Formatting Data&quot;">​</a></h3><p>Suppose you have a CSV file with messy data. You can say:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me clean up this CSV file. Make sure every column has a header, remove empty rows, and unify the date format to YYYY-MM-DD.</span></span></code></pre></div><p>Codex will read the file, modify the content, and save the result.</p><hr><h2 id="vi-in-lesson-practice-checklist" tabindex="-1">VI. In-Lesson Practice Checklist <a class="header-anchor" href="#vi-in-lesson-practice-checklist" aria-label="Permalink to &quot;VI. In-Lesson Practice Checklist&quot;">​</a></h2><p>Complete the following tasks in order:</p><ul><li>[ ] Create a test folder and put different types of files in it (.txt, .pdf, .jpg, .xlsx)</li><li>[ ] Have Codex count the files and show the type distribution</li><li>[ ] Have Codex automatically classify files by type into different subfolders</li><li>[ ] Have Codex batch rename a set of files</li><li>[ ] Have Codex analyze the folder&#39;s disk space usage</li></ul><hr><h2 id="vii-summary" tabindex="-1">VII. Summary <a class="header-anchor" href="#vii-summary" aria-label="Permalink to &quot;VII. Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th></tr></thead><tbody><tr><td>Read files</td><td>Supports text, code, images, PDF, and more</td></tr><tr><td>Read folders</td><td>List file trees, show statistics</td></tr><tr><td>Edit files</td><td>Modify file content directly</td></tr><tr><td>Batch operations</td><td>Rename, move, classify, format</td></tr><tr><td>Space analysis</td><td>View file sizes and disk usage</td></tr></tbody></table><hr><h2 id="viii-next-step" tabindex="-1">VIII. Next Step <a class="header-anchor" href="#viii-next-step" aria-label="Permalink to &quot;VIII. Next Step&quot;">​</a></h2><p><a href="./lesson-9.html">→ Lesson 9: Natural Language Driven</a></p>`,62)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
